import json
d = json.load(open('/work/workspace/deliverable/parecer.json'))

def walk(o, path=''):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, f'{path}/{k}')
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from walk(v, f'{path}[{i}]')
    else:
        yield path, o

hits = [(p, v) for p, v in walk(d)
        if isinstance(v, (int, float)) and any(t in p for t in ('total', 'verbas_', 'indenizacao_', 'dano_'))]
for p, v in hits:
    print(p, '=', v)

comp = {}
for p, v in hits:
    name = p.rsplit('/', 1)[-1]
    if name in ('verbas_rescisorias', 'indenizacao_estabilidade', 'dano_moral', 'total'):
        comp[name] = v
s = comp.get('verbas_rescisorias', 0) + comp.get('indenizacao_estabilidade', 0) + comp.get('dano_moral', 0)
print('sum of components =', round(s, 2), '| total in JSON =', comp.get('total'),
      '| match:', round(s, 2) == comp.get('total'))
print('justa_causa_cabivel =', json.dumps(json.load(open('/work/workspace/deliverable/parecer.json'))).count('justa_causa_cabivel'), 'occurrence(s)')

